mkitem!{mktrait!{# [doc = " A hashable type."] # [doc = ""] # [doc = " Types implementing `Hash` are able to be [`hash`]ed with an instance of"] # [doc = " [`Hasher`]."] # [doc = ""] # [doc = " ## Implementing `Hash`"] # [doc = ""] # [doc = " You can derive `Hash` with `#[derive(Hash)]` if all fields implement `Hash`."] # [doc = " The resulting hash will be the combination of the values from calling"] # [doc = " [`hash`] on each field."] # [doc = ""] # [doc = " ```"] # [doc = " #[derive(Hash)]"] # [doc = " struct Rustacean {"] # [doc = "     name: String,"] # [doc = "     country: String,"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " If you need more control over how a value is hashed, you can of course"] # [doc = " implement the `Hash` trait yourself:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{Hash, Hasher};"] # [doc = ""] # [doc = " struct Person {"] # [doc = "     id: u32,"] # [doc = "     name: String,"] # [doc = "     phone: u64,"] # [doc = " }"] # [doc = ""] # [doc = " impl Hash for Person {"] # [doc = "     fn hash<H: Hasher>(&self, state: &mut H) {"] # [doc = "         self.id.hash(state);"] # [doc = "         self.phone.hash(state);"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## `Hash` and `Eq`"] # [doc = ""] # [doc = " When implementing both `Hash` and [`Eq`], it is important that the following"] # [doc = " property holds:"] # [doc = ""] # [doc = " ```text"] # [doc = " k1 == k2 -> hash(k1) == hash(k2)"] # [doc = " ```"] # [doc = ""] # [doc = " In other words, if two keys are equal, their hashes must also be equal."] # [doc = " [`HashMap`] and [`HashSet`] both rely on this behavior."] # [doc = ""] # [doc = " Thankfully, you won't need to worry about upholding this property when"] # [doc = " deriving both [`Eq`] and `Hash` with `#[derive(PartialEq, Eq, Hash)]`."] # [doc = ""] # [doc = " Violating this property is a logic error. The behavior resulting from a logic error is not"] # [doc = " specified, but users of the trait must ensure that such logic errors do *not* result in"] # [doc = " undefined behavior. This means that `unsafe` code **must not** rely on the correctness of these"] # [doc = " methods."] # [doc = ""] # [doc = " ## Prefix collisions"] # [doc = ""] # [doc = " Implementations of `hash` should ensure that the data they"] # [doc = " pass to the `Hasher` are prefix-free. That is,"] # [doc = " values which are not equal should cause two different sequences of values to be written,"] # [doc = " and neither of the two sequences should be a prefix of the other."] # [doc = ""] # [doc = " For example, the standard implementation of [`Hash` for `&str`][impl] passes an extra"] # [doc = " `0xFF` byte to the `Hasher` so that the values `(\"ab\", \"c\")` and `(\"a\","] # [doc = " \"bc\")` hash differently."] # [doc = ""] # [doc = " ## Portability"] # [doc = ""] # [doc = " Due to differences in endianness and type sizes, data fed by `Hash` to a `Hasher`"] # [doc = " should not be considered portable across platforms. Additionally the data passed by most"] # [doc = " standard library types should not be considered stable between compiler versions."] # [doc = ""] # [doc = " This means tests shouldn't probe hard-coded hash values or data fed to a `Hasher` and"] # [doc = " instead should check consistency with `Eq`."] # [doc = ""] # [doc = " Serialization formats intended to be portable between platforms or compiler versions should"] # [doc = " either avoid encoding hashes or only rely on `Hash` and `Hasher` implementations that"] # [doc = " provide additional guarantees."] # [doc = ""] # [doc = " [`HashMap`]: ../../std/collections/struct.HashMap.html"] # [doc = " [`HashSet`]: ../../std/collections/struct.HashSet.html"] # [doc = " [`hash`]: Hash::hash"] # [doc = " [impl]: ../../std/primitive.str.html#impl-Hash-for-str"] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_diagnostic_item = "Hash"] pub trait Hash : marker :: PointeeSized { # [doc = " Feeds this value into the given [`Hasher`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{DefaultHasher, Hash, Hasher};"] # [doc = ""] # [doc = " let mut hasher = DefaultHasher::new();"] # [doc = " 7920.hash(&mut hasher);"] # [doc = " println!(\"Hash is {:x}!\", hasher.finish());"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] fn hash < H : Hasher > (& self , state : & mut H) ; # [doc = " Feeds a slice of this type into the given [`Hasher`]."] # [doc = ""] # [doc = " This method is meant as a convenience, but its implementation is"] # [doc = " also explicitly left unspecified. It isn't guaranteed to be"] # [doc = " equivalent to repeated calls of [`hash`] and implementations of"] # [doc = " [`Hash`] should keep that in mind and call [`hash`] themselves"] # [doc = " if the slice isn't treated as a whole unit in the [`PartialEq`]"] # [doc = " implementation."] # [doc = ""] # [doc = " For example, a [`VecDeque`] implementation might naïvely call"] # [doc = " [`as_slices`] and then [`hash_slice`] on each slice, but this"] # [doc = " is wrong since the two slices can change with a call to"] # [doc = " [`make_contiguous`] without affecting the [`PartialEq`]"] # [doc = " result. Since these slices aren't treated as singular"] # [doc = " units, and instead part of a larger deque, this method cannot"] # [doc = " be used."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{DefaultHasher, Hash, Hasher};"] # [doc = ""] # [doc = " let mut hasher = DefaultHasher::new();"] # [doc = " let numbers = [6, 28, 496, 8128];"] # [doc = " Hash::hash_slice(&numbers, &mut hasher);"] # [doc = " println!(\"Hash is {:x}!\", hasher.finish());"] # [doc = " ```"] # [doc = ""] # [doc = " [`VecDeque`]: ../../std/collections/struct.VecDeque.html"] # [doc = " [`as_slices`]: ../../std/collections/struct.VecDeque.html#method.as_slices"] # [doc = " [`make_contiguous`]: ../../std/collections/struct.VecDeque.html#method.make_contiguous"] # [doc = " [`hash`]: Hash::hash"] # [doc = " [`hash_slice`]: Hash::hash_slice"] # [stable (feature = "hash_slice" , since = "1.3.0")] fn hash_slice < H : Hasher > (data : & [Self] , state : & mut H) where Self : Sized , { for piece in data { piece . hash (state) } } }}}
