mkitem!{mktrait!{# [doc = " A trait for hashing an arbitrary stream of bytes."] # [doc = ""] # [doc = " Instances of `Hasher` usually represent state that is changed while hashing"] # [doc = " data."] # [doc = ""] # [doc = " `Hasher` provides a fairly basic interface for retrieving the generated hash"] # [doc = " (with [`finish`]), and writing integers as well as slices of bytes into an"] # [doc = " instance (with [`write`] and [`write_u8`] etc.). Most of the time, `Hasher`"] # [doc = " instances are used in conjunction with the [`Hash`] trait."] # [doc = ""] # [doc = " This trait provides no guarantees about how the various `write_*` methods are"] # [doc = " defined and implementations of [`Hash`] should not assume that they work one"] # [doc = " way or another. You cannot assume, for example, that a [`write_u32`] call is"] # [doc = " equivalent to four calls of [`write_u8`].  Nor can you assume that adjacent"] # [doc = " `write` calls are merged, so it's possible, for example, that"] # [doc = " ```"] # [doc = " # fn foo(hasher: &mut impl std::hash::Hasher) {"] # [doc = " hasher.write(&[1, 2]);"] # [doc = " hasher.write(&[3, 4, 5, 6]);"] # [doc = " # }"] # [doc = " ```"] # [doc = " and"] # [doc = " ```"] # [doc = " # fn foo(hasher: &mut impl std::hash::Hasher) {"] # [doc = " hasher.write(&[1, 2, 3, 4]);"] # [doc = " hasher.write(&[5, 6]);"] # [doc = " # }"] # [doc = " ```"] # [doc = " end up producing different hashes."] # [doc = ""] # [doc = " Thus to produce the same hash value, [`Hash`] implementations must ensure"] # [doc = " for equivalent items that exactly the same sequence of calls is made -- the"] # [doc = " same methods with the same parameters in the same order."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{DefaultHasher, Hasher};"] # [doc = ""] # [doc = " let mut hasher = DefaultHasher::new();"] # [doc = ""] # [doc = " hasher.write_u32(1989);"] # [doc = " hasher.write_u8(11);"] # [doc = " hasher.write_u8(9);"] # [doc = " hasher.write(b\"Huh?\");"] # [doc = ""] # [doc = " println!(\"Hash is {:x}!\", hasher.finish());"] # [doc = " ```"] # [doc = ""] # [doc = " [`finish`]: Hasher::finish"] # [doc = " [`write`]: Hasher::write"] # [doc = " [`write_u8`]: Hasher::write_u8"] # [doc = " [`write_u32`]: Hasher::write_u32"] # [stable (feature = "rust1" , since = "1.0.0")] pub trait Hasher { # [doc = " Returns the hash value for the values written so far."] # [doc = ""] # [doc = " Despite its name, the method does not reset the hasher’s internal"] # [doc = " state. Additional [`write`]s will continue from the current value."] # [doc = " If you need to start a fresh hash value, you will have to create"] # [doc = " a new hasher."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{DefaultHasher, Hasher};"] # [doc = ""] # [doc = " let mut hasher = DefaultHasher::new();"] # [doc = " hasher.write(b\"Cool!\");"] # [doc = ""] # [doc = " println!(\"Hash is {:x}!\", hasher.finish());"] # [doc = " ```"] # [doc = ""] # [doc = " [`write`]: Hasher::write"] # [stable (feature = "rust1" , since = "1.0.0")] # [must_use] fn finish (& self) -> u64 ; # [doc = " Writes some data into this `Hasher`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{DefaultHasher, Hasher};"] # [doc = ""] # [doc = " let mut hasher = DefaultHasher::new();"] # [doc = " let data = [0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef];"] # [doc = ""] # [doc = " hasher.write(&data);"] # [doc = ""] # [doc = " println!(\"Hash is {:x}!\", hasher.finish());"] # [doc = " ```"] # [doc = ""] # [doc = " # Note to Implementers"] # [doc = ""] # [doc = " You generally should not do length-prefixing as part of implementing"] # [doc = " this method.  It's up to the [`Hash`] implementation to call"] # [doc = " [`Hasher::write_length_prefix`] before sequences that need it."] # [stable (feature = "rust1" , since = "1.0.0")] fn write (& mut self , bytes : & [u8]) ; # [doc = " Writes a single `u8` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_u8 (& mut self , i : u8) { self . write (& [i]) } # [doc = " Writes a single `u16` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_u16 (& mut self , i : u16) { self . write (& i . to_ne_bytes ()) } # [doc = " Writes a single `u32` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_u32 (& mut self , i : u32) { self . write (& i . to_ne_bytes ()) } # [doc = " Writes a single `u64` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_u64 (& mut self , i : u64) { self . write (& i . to_ne_bytes ()) } # [doc = " Writes a single `u128` into this hasher."] # [inline] # [stable (feature = "i128" , since = "1.26.0")] fn write_u128 (& mut self , i : u128) { self . write (& i . to_ne_bytes ()) } # [doc = " Writes a single `usize` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_usize (& mut self , i : usize) { self . write (& i . to_ne_bytes ()) } # [doc = " Writes a single `i8` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_i8 (& mut self , i : i8) { self . write_u8 (i as u8) } # [doc = " Writes a single `i16` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_i16 (& mut self , i : i16) { self . write_u16 (i as u16) } # [doc = " Writes a single `i32` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_i32 (& mut self , i : i32) { self . write_u32 (i as u32) } # [doc = " Writes a single `i64` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_i64 (& mut self , i : i64) { self . write_u64 (i as u64) } # [doc = " Writes a single `i128` into this hasher."] # [inline] # [stable (feature = "i128" , since = "1.26.0")] fn write_i128 (& mut self , i : i128) { self . write_u128 (i as u128) } # [doc = " Writes a single `isize` into this hasher."] # [inline] # [stable (feature = "hasher_write" , since = "1.3.0")] fn write_isize (& mut self , i : isize) { self . write_usize (i as usize) } # [doc = " Writes a length prefix into this hasher, as part of being prefix-free."] # [doc = ""] # [doc = " If you're implementing [`Hash`] for a custom collection, call this before"] # [doc = " writing its contents to this `Hasher`.  That way"] # [doc = " `(collection![1, 2, 3], collection![4, 5])` and"] # [doc = " `(collection![1, 2], collection![3, 4, 5])` will provide different"] # [doc = " sequences of values to the `Hasher`"] # [doc = ""] # [doc = " The `impl<T> Hash for [T]` includes a call to this method, so if you're"] # [doc = " hashing a slice (or array or vector) via its `Hash::hash` method,"] # [doc = " you should **not** call this yourself."] # [doc = ""] # [doc = " This method is only for providing domain separation.  If you want to"] # [doc = " hash a `usize` that represents part of the *data*, then it's important"] # [doc = " that you pass it to [`Hasher::write_usize`] instead of to this method."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(hasher_prefixfree_extras)]"] # [doc = " # // Stubs to make the `impl` below pass the compiler"] # [doc = " # #![allow(non_local_definitions)]"] # [doc = " # struct MyCollection<T>(Option<T>);"] # [doc = " # impl<T> MyCollection<T> {"] # [doc = " #     fn len(&self) -> usize { todo!() }"] # [doc = " # }"] # [doc = " # impl<'a, T> IntoIterator for &'a MyCollection<T> {"] # [doc = " #     type Item = T;"] # [doc = " #     type IntoIter = std::iter::Empty<T>;"] # [doc = " #     fn into_iter(self) -> Self::IntoIter { todo!() }"] # [doc = " # }"] # [doc = ""] # [doc = " use std::hash::{Hash, Hasher};"] # [doc = " impl<T: Hash> Hash for MyCollection<T> {"] # [doc = "     fn hash<H: Hasher>(&self, state: &mut H) {"] # [doc = "         state.write_length_prefix(self.len());"] # [doc = "         for elt in self {"] # [doc = "             elt.hash(state);"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # Note to Implementers"] # [doc = ""] # [doc = " If you've decided that your `Hasher` is willing to be susceptible to"] # [doc = " Hash-DoS attacks, then you might consider skipping hashing some or all"] # [doc = " of the `len` provided in the name of increased performance."] # [inline] # [unstable (feature = "hasher_prefixfree_extras" , issue = "96762")] fn write_length_prefix (& mut self , len : usize) { self . write_usize (len) ; } # [doc = " Writes a single `str` into this hasher."] # [doc = ""] # [doc = " If you're implementing [`Hash`], you generally do not need to call this,"] # [doc = " as the `impl Hash for str` does, so you should prefer that instead."] # [doc = ""] # [doc = " This includes the domain separator for prefix-freedom, so you should"] # [doc = " **not** call `Self::write_length_prefix` before calling this."] # [doc = ""] # [doc = " # Note to Implementers"] # [doc = ""] # [doc = " There are at least two reasonable default ways to implement this."] # [doc = " Which one will be the default is not yet decided, so for now"] # [doc = " you probably want to override it specifically."] # [doc = ""] # [doc = " ## The general answer"] # [doc = ""] # [doc = " It's always correct to implement this with a length prefix:"] # [doc = ""] # [doc = " ```"] # [doc = " # #![feature(hasher_prefixfree_extras)]"] # [doc = " # struct Foo;"] # [doc = " # impl std::hash::Hasher for Foo {"] # [doc = " # fn finish(&self) -> u64 { unimplemented!() }"] # [doc = " # fn write(&mut self, _bytes: &[u8]) { unimplemented!() }"] # [doc = " fn write_str(&mut self, s: &str) {"] # [doc = "     self.write_length_prefix(s.len());"] # [doc = "     self.write(s.as_bytes());"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " And, if your `Hasher` works in `usize` chunks, this is likely a very"] # [doc = " efficient way to do it, as anything more complicated may well end up"] # [doc = " slower than just running the round with the length."] # [doc = ""] # [doc = " ## If your `Hasher` works byte-wise"] # [doc = ""] # [doc = " One nice thing about `str` being UTF-8 is that the `b'\\xFF'` byte"] # [doc = " never happens.  That means that you can append that to the byte stream"] # [doc = " being hashed and maintain prefix-freedom:"] # [doc = ""] # [doc = " ```"] # [doc = " # #![feature(hasher_prefixfree_extras)]"] # [doc = " # struct Foo;"] # [doc = " # impl std::hash::Hasher for Foo {"] # [doc = " # fn finish(&self) -> u64 { unimplemented!() }"] # [doc = " # fn write(&mut self, _bytes: &[u8]) { unimplemented!() }"] # [doc = " fn write_str(&mut self, s: &str) {"] # [doc = "     self.write(s.as_bytes());"] # [doc = "     self.write_u8(0xff);"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " This does require that your implementation not add extra padding, and"] # [doc = " thus generally requires that you maintain a buffer, running a round"] # [doc = " only once that buffer is full (or `finish` is called)."] # [doc = ""] # [doc = " That's because if `write` pads data out to a fixed chunk size, it's"] # [doc = " likely that it does it in such a way that `\"a\"` and `\"a\\x00\"` would"] # [doc = " end up hashing the same sequence of things, introducing conflicts."] # [inline] # [unstable (feature = "hasher_prefixfree_extras" , issue = "96762")] fn write_str (& mut self , s : & str) { self . write (s . as_bytes ()) ; self . write_u8 (0xff) ; } }}}
