mkitem!{mktrait!{# [doc = " A trait for creating instances of [`Hasher`]."] # [doc = ""] # [doc = " A `BuildHasher` is typically used (e.g., by [`HashMap`]) to create"] # [doc = " [`Hasher`]s for each key such that they are hashed independently of one"] # [doc = " another, since [`Hasher`]s contain state."] # [doc = ""] # [doc = " For each instance of `BuildHasher`, the [`Hasher`]s created by"] # [doc = " [`build_hasher`] should be identical. That is, if the same stream of bytes"] # [doc = " is fed into each hasher, the same output will also be generated."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{BuildHasher, Hasher, RandomState};"] # [doc = ""] # [doc = " let s = RandomState::new();"] # [doc = " let mut hasher_1 = s.build_hasher();"] # [doc = " let mut hasher_2 = s.build_hasher();"] # [doc = ""] # [doc = " hasher_1.write_u32(8128);"] # [doc = " hasher_2.write_u32(8128);"] # [doc = ""] # [doc = " assert_eq!(hasher_1.finish(), hasher_2.finish());"] # [doc = " ```"] # [doc = ""] # [doc = " [`build_hasher`]: BuildHasher::build_hasher"] # [doc = " [`HashMap`]: ../../std/collections/struct.HashMap.html"] # [stable (since = "1.7.0" , feature = "build_hasher")] pub trait BuildHasher { # [doc = " Type of the hasher that will be created."] # [stable (since = "1.7.0" , feature = "build_hasher")] type Hasher : Hasher ; # [doc = " Creates a new hasher."] # [doc = ""] # [doc = " Each call to `build_hasher` on the same instance should produce identical"] # [doc = " [`Hasher`]s."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::hash::{BuildHasher, RandomState};"] # [doc = ""] # [doc = " let s = RandomState::new();"] # [doc = " let new_s = s.build_hasher();"] # [doc = " ```"] # [stable (since = "1.7.0" , feature = "build_hasher")] fn build_hasher (& self) -> Self :: Hasher ; # [doc = " Calculates the hash of a single value."] # [doc = ""] # [doc = " This is intended as a convenience for code which *consumes* hashes, such"] # [doc = " as the implementation of a hash table or in unit tests that check"] # [doc = " whether a custom [`Hash`] implementation behaves as expected."] # [doc = ""] # [doc = " This must not be used in any code which *creates* hashes, such as in an"] # [doc = " implementation of [`Hash`].  The way to create a combined hash of"] # [doc = " multiple values is to call [`Hash::hash`] multiple times using the same"] # [doc = " [`Hasher`], not to call this method repeatedly and combine the results."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use std::cmp::{max, min};"] # [doc = " use std::hash::{BuildHasher, Hash, Hasher};"] # [doc = " struct OrderAmbivalentPair<T: Ord>(T, T);"] # [doc = " impl<T: Ord + Hash> Hash for OrderAmbivalentPair<T> {"] # [doc = "     fn hash<H: Hasher>(&self, hasher: &mut H) {"] # [doc = "         min(&self.0, &self.1).hash(hasher);"] # [doc = "         max(&self.0, &self.1).hash(hasher);"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // Then later, in a `#[test]` for the type..."] # [doc = " let bh = std::hash::RandomState::new();"] # [doc = " assert_eq!("] # [doc = "     bh.hash_one(OrderAmbivalentPair(1, 2)),"] # [doc = "     bh.hash_one(OrderAmbivalentPair(2, 1))"] # [doc = " );"] # [doc = " assert_eq!("] # [doc = "     bh.hash_one(OrderAmbivalentPair(10, 2)),"] # [doc = "     bh.hash_one(&OrderAmbivalentPair(2, 10))"] # [doc = " );"] # [doc = " ```"] # [stable (feature = "build_hasher_simple_hash_one" , since = "1.71.0")] fn hash_one < T : Hash > (& self , x : T) -> u64 where Self : Sized , Self :: Hasher : Hasher , { let mut hasher = self . build_hasher () ; x . hash (& mut hasher) ; hasher . finish () } }}}
